// Metro requires static imports. Keep every public feature dependency reachable.
import fs from 'node:fs';
import path from 'node:path';
import { registryEntries } from './registry-entries.mjs';
const root = path.resolve(import.meta.dirname, '..');
const entries = registryEntries(root);
const text = [
  '// Generated by scripts/generate-registry.mjs; edit package.json, then regenerate.',
  ...entries.map((entry, index) => `import * as Module${index} from '${entry}';`), '',
  "import * as EygWidgets from './widgets';", '',
  "import * as EygBackground from './background-api';", '',
  'export const expoModules: Record<string, unknown> = {',
  "  'eyg-widgets': EygWidgets,",
  "  'eyg-background': EygBackground,",
  ...entries.map((entry, index) => `  '${entry}': Module${index},`), '};', '',
].join('\n');
const output = path.join(root, 'src/modules.ts');
if (process.argv.includes('--check')) {
  if (fs.readFileSync(output, 'utf8') !== text) throw new Error('Expo registry is stale; run npm run generate:registry');
} else fs.writeFileSync(output, text);
